-- Chains to start early, before you reach the dungeon.
ns.EARLY_CHAINS = {
    "|cffffd100Hidden Enemies|r (RFC): get the Lieutenant's Insignia from Burning Blade in Skull Rock, east of the Orgrimmar gate. It has a low drop rate.",
    "|cffffd100Leaders of the Fang|r (WC): start Tonga Runetotem's oasis chain at the Crossroads around level 14, then go to Hamuul and Nara in Thunder Bluff.",
    "|cffffd100Raptor Horns|r (Mebok, Ratchet): unlocks Smart Drinks for WC.",
    "|cffffd100Test of Lore|r (SM Library): a 10-step chain that starts with Dorn Plainstalker in Thousand Needles and runs through Stonetalon and Undercity.",
    "|cffffd100Going, Going, Guano!|r (RFK): unlocks Hearts of Zeal for Scarlet Monastery.",
    "|cffffd100The Spider God|r (ZF): Venom Bottles in the Hinterlands -> Apothecary Lydon in Tarren Mill -> Master Gadrin in Sen'jin.",
    "|cffffd100Screecher Spirits|r (Yeh'kinya, Tanaris): needs Feralas kills, then leads into ZF and later The God Hakkar in Sunken Temple.",
    "|cffffd100Gahz'rilla|r (ZF): you need the Mallet of Zul'Farrak, made from the Sacred Mallet (Altar of Zul, Hinterlands) at Jintha'Alor.",
    "|cffffd100Sunken Temple|r: Fel'zerul's chain in Stonard sends you to the Hinterlands; Uzer'i's breadcrumb in Feralas sends you to Tanaris and Ratchet.",
    "|cffffd100Scholomance key|r: the Bulwark chain in Western Plaguelands (A Call to Arms -> Mission Accomplished!) is required before the key quests.",
}

-- The route: dungeons in level order, and what to pick up (hub by hub) before each run.
ns.ROUTE = {
    { levels = "9-16", title = "Ragefire Chasm", runs = "RFC", picks = { { "Orgrimmar", "Thrall: Hidden Enemies (after the Skull Rock insignia); Neeru Fireblade: Slaying the Beast" }, { "Thunder Bluff", "Rahauro: Testing an Enemy's Strength, Searching for the Lost Satchel" }, { "Undercity", "Varimathras: The Power to Destroy..." } }, tip = "The Thunder Bluff and Undercity pickups are far from Orgrimmar. Grab them only if you pass through anyway; you'll be back in both cities for WC and Ruins of Lordaeron." },
    { levels = "14-22", title = "Wailing Caverns", runs = "WC", picks = { { "Crossroads", "Tonga Runetotem: The Barrens Oases chain -> Altered Beings" }, { "Ratchet", "Crane Operator Bigglefuzz: Trouble at the Docks; Mebok Mizzyrix: Raptor Horns -> Smart Drinks" }, { "Thunder Bluff", "Apothecary Zamah: Serpentbloom; Hamuul -> Nara Wildmane: Leaders of the Fang" }, { "Cave above WC", "Ebru: Deviate Eradication; Nalpak: Deviate Hides" } }, tip = "After the run: Glowing Shard -> Sputtervalve (Ratchet) -> Falla Sagewind (hill above WC) -> Hamuul in Thunder Bluff." },
    { levels = "20-27", title = "Ruins of Lordaeron, then Shadowfang Keep", runs = "RoL + SFK in one trip west", picks = { { "Undercity", "Morbin Lightbane: Light's Justice; Theodore Griffs: The New Plague; Keeper Bel'dugur: The Book of Ur" }, { "Tirisfal", "Deathguard Kristof (tents between Undercity and Brill): The Wrath of Rath'mael" }, { "The Sepulcher", "Tabitha Heartweaver: A Frightened Request; High Executor Hadrec: Deathstalkers in Shadowfang; Dalar Dawnweaver: Arugal Must Die" } }, tip = "Run Ruins of Lordaeron first (quests are level 21-22), then do the Unending Torment steps inside Undercity and hand the Crest to Oran Snakewrithe. Then run SFK (quests 25-27). Warlocks: take The Orb of Soran'ruk from Doan Karhan in the Barrens before this trip, because it needs fragments from both SFK and BFD." },
    { levels = "22-27", title = "Blackfathom Deeps", runs = "BFD", picks = { { "Stonetalon (Sunrock Retreat)", "Tsunaman: Trouble in the Deeps" }, { "Ashenvale (Zoram'gar)", "Je'neu Sancrea: The Essence of Aku'Mai, Amongst the Ruins" } }, tip = "Inside: the Damp Note (Tide Priestess drop) starts Allegiance to the Old Gods, and Argent Guard Thaelrid gives Blackfathom Villainy. Save the Thunder Bluff turn-in (Bashana) for the Excavation Site relic, which goes to the same NPC." },
    { levels = "24-30", title = "Excavation Site (new)", runs = "Wetlands", picks = { { "Orgrimmar", "Borstan (the Drag): Changing Tastes" }, { "Arathi (Hammerfall)", "Zaruk: Dragonmaw Rumors -> Open the Maw (Deathstalker Agent at the entrance)" } }, tip = "The final boss drops the Titan Relic: take it to Bashana in Thunder Bluff, then Muln Earthfury in Mulgore. Hammerfall is next to Hillsbrad, so start Dalaran's access chain on the same trip if you're close to 28." },
    { levels = "28-33", title = "City of Dalaran (new)", runs = "Alterac Mountains", picks = { { "Tarren Mill", "Magus Wordeen Voidglare: Prison Break In -> Dalaran Patrols, Key to the City, Blood in the Streets -> Heart of Disruption (gives the Dalaran Sewer Key); Melisara: The Grave Knight" }, { "Undercity", "Doctor Martin Felben: Source of Power" }, { "Sewer entrance", "Rexxie Copperclutch: Opportunistic Education" } }, tip = "The dungeon quests show as level 33 on Wowhead, so finishing the access chain around 28-30 lines up well." },
    { levels = "29-38", title = "Razorfen Kraul, Gnomeregan, SM Graveyard and Library", runs = "RFK + Gnomer + SM GY/Lib", picks = { { "Ratchet", "Mebok Mizzyrix: Blueleaf Tubers" }, { "Thunder Bluff", "Auld Stonespire: A Vengeful Fate; Sage Truthseeker: Compendium of the Fallen (not for Undead)" }, { "Undercity", "Master Apothecary Faranell: Going, Going, Guano! (then Hearts of Zeal)" }, { "Orgrimmar", "Nogg: Rig Wars; Sovik: Chief Engineer Scooty -> Booty Bay for the Goblin Transponder" } }, tip = "Charlga Razorflank in RFK drops the Small Scroll (An Unholy Alliance) for Varimathras. Its follow-up is killing Ambassador Malcin outside Razorfen Downs, so hold it for that trip. Vorrel's Revenge starts inside SM Graveyard and ends in Tarren Mill after killing Nancy Vishas in Alterac." },
    { levels = "35-44", title = "Razorfen Downs, SM Armory and Cathedral, The Drowned City", runs = "RFD + SM Arm/Cath + Drowned City", picks = { { "Undercity", "Varimathras: Into The Scarlet Monastery, An Unholy Alliance (kill Malcin); Andrew Brownell: Bring the End" }, { "Outside RFD", "Myriam Moonsinger: A Host of Evil" } }, tip = "The Drowned City (35-40) isn't in the beta. One datamined quest exists (rubbings of four tablets, Darkspear and Orgrimmar rep), but its giver is unknown." },
    { levels = "40-45", title = "Krol'dok Stronghold (new)", runs = "Riverglades", picks = { { "Rog'mar (Horde hub, Riverglades)", "No quests published yet" } }, tip = "Blizzard set the level range to 40-45. Quest items like the Krol'dok Moulding exist in the client, but no quests are known." },
    { levels = "41-51", title = "Uldaman and Zul'Farrak", runs = "Ulda + ZF", picks = { { "Badlands", "Rigglefuzz: Power Stones; Theldurin: Solution to Doom; Jarkal Mossmeld (Kargath): Badlands -> Uldaman Reagent Run" }, { "Orgrimmar", "Dran Droffers: Necklace Recovery; Master Gadrin (Sen'jin): The Spider God" }, { "Undercity", "Patrick Garrett: Reclaimed Treasures" }, { "Tanaris", "Gadgetzan: Tran'rek, Trenton Lighthammer, Bilgewhizzle; Steamwheedle Port: Yeh'kinya" }, { "Elsewhere", "Tabetha (Dustwallow): Tiara of the Deep; Wizzle Brassbolts (Shimmering Flats): Gahz'rilla" } }, tip = "The Platinum Discs at the end of Uldaman go to Sage Truthseeker in Thunder Bluff. One Hinterlands visit can cover the Spider God venom, the Sacred Mallet and, later, the Atal'ai Exile for Sunken Temple." },
    { levels = "45-55", title = "Maraudon, Alcaz Island Prison, Sunken Temple", runs = "Mara + Alcaz + ST", picks = { { "Orgrimmar", "Uthel'nay: Shadowshard Fragments" }, { "Desolace", "Shadowprey: Vark Battlescar, Selendra; Willow; Centaur Pariah; Cavindra (outside Maraudon)" }, { "Stonard", "Fel'zerul: Pool of Tears -> The Atal'ai Exile (Hinterlands) -> The Temple of Atal'Hakkar; Exile also gives Jammal'an the Prophet" }, { "Feralas -> Tanaris -> Ratchet", "Uzer'i -> Marvon Rivetseeker -> The Stone Circle (Ratchet), unlocking Into the Depths and Secret of the Circle" }, { "Ratchet / Un'Goro", "Liv Rizzlefix and Larion: Zapper Fuel; Yeh'kinya: The Ancient Egg -> The God Hakkar" } }, tip = "Alcaz Island Prison (48-53) isn't in the beta and has no known quests. Every class has a level 50 Sunken Temple quest that starts at its trainer." },
    { levels = "52-60", title = "Blackrock Depths, Lower Blackrock Spire, Dire Maul East", runs = "BRD + LBRS + DME (+ Blackmaw Hold)", picks = { { "Kargath", "Thunderheart, Galamav, Lexlort, Warlord Goretooth, Theodora Mulvadania, Vivian Lagrave, the KILL ON SIGHT posters" }, { "Orgrimmar", "Thrall: Royal Rescue chain (after Commander Gor'shak)" }, { "Undercity", "Apothecary Zinge: Vivian Lagrave quests" }, { "Burning Steppes", "Flame Crest: Kibler, Maxwort, Yuka Screwspigot (from Yorba in Tanaris); Cyrus Therepentous" }, { "Feralas", "Camp Mojache: Talo Thornhoof, Sage Korolusk; Azj'Tordin (Lariss Pavilion)" } }, tip = "Dark Iron Legacy (Franclorn Forgewright on the Blackrock Mountain bridge) gives the Shadowforge Key. Blackmaw Hold (55-60, Azshara) has quests according to the developers, but none are published." },
    { levels = "58-60", title = "Endgame dungeons and attunements", runs = "Strat, Scholo, UBRS, DM West/North, Shaper's Terrace", picks = { { "Light's Hope", "Betina Bigglezink, Leonid Barthalomew, Duke Zverenhoff, Caretaker Alen, Smokey LaRue" }, { "Plaguelands", "Nathanos Blightcaller (Ramstein); Bulwark chain -> Scholomance key; Eva Sarkhoff and Magistrate Marduke (Caer Darrow)" }, { "Kargath / Orgrimmar", "Warlord's Command -> For The Horde! -> the Onyxia attunement chain" } }, tip = "Raids and their attunements open December 9, 2026." },
}
